#define NUM_LAYERS 8.
#define TAU 6.28318
#define PI 3.141592
#define Velocity .025 //modified value to increse or decrease speed, negative value travel backwards
#define StarGlow 0.025
#define StarSize 02.
#define CanvasView 20.


float Star(vec2 uv, float flare){
    float d = length(uv);
  	float m = sin(StarGlow*1.2)/d;  
    float rays = max(0., .5-abs(uv.x*uv.y*1000.)); 
    m += (rays*flare)*2.;
    m *= smoothstep(1., .1, d);
    return m;
}

float Hash21(vec2 p){
    p = fract(p*vec2(123.34, 456.21));
    p += dot(p, p+45.32);
    return fract(p.x*p.y);
}


vec3 StarLayer(vec2 uv){
    vec3 col = vec3(0);
    vec2 gv = fract(uv);
    vec2 id = floor(uv);
    for(int y=-1;y<=1;y++){
        for(int x=-1; x<=1; x++){
            vec2 offs = vec2(x,y);
            float n = Hash21(id+offs);
            float size = fract(n);
            float star = Star(gv-offs-vec2(n, fract(n*34.))+.5, smoothstep(.1,.9,size)*.46);
            vec3 color = sin(vec3(3.2,.3,.9)*fract(n*2345.2)*TAU)*.25+.75;
            color = color*vec3(0.9,0.59,.9+size);
            star *= sin(iTime*1.0+n*TAU)*.5+.5;
            col += star*size*color;
        }
    }
    return col;
}
#define COLOR vec3(0.1, 0.2, 1.)
//#define COLOR (sin(time*vec3(.345, .456, .657))*.4+.6)
#define OFFSET vec2(0.5*cos(0.5*time-sin(time*0.5)), 0.5*sin(0.5*time+cos(time*0.75)))
#define time iTime*0.

float saturate(float x){
    return clamp(x,0.0,1.0);
}

vec3 CenterLight(vec2 p){
    p -= OFFSET;

    p *= 12.;
 	float l = 1. / dot(p, p);
    return l*l * COLOR;
}
vec3 Straws(vec2 p){
    p -= OFFSET;
    float t3 = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(p.xy) + .07)) * 2.2;
	float si = sin(t3);
	float co = cos(t3);
	mat2 ma = mat2(co, si, -si, co);
   p*=ma;
	float a = atan(p.y, p.x);
    float d = dot(p,p);

    float l = saturate(1.-length(p));

    l *= 0.5 + 0.5*sin(a*50.+d*5.+sin(time*0.)*20.);

    l *= 0.5 + 0.3 * sin(d*10.+a*10.-time*0.);
    return l*l*COLOR;
}
vec3 Lights(vec2 p){
    p -= OFFSET;
    float t3 = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(p.xy) + .07)) * 2.2;
	float si = sin(t3);
	float co = cos(t3);
	mat2 ma = mat2(co, si, -si, co);
   p*=ma;
    float res = 0.0;

    for(float i = 0.; i < 500.; ++i){
        float t = time*0. + i*i;

        vec2 q = p + vec2(cos(t), sin(t)) * sin(i*11.+time*0.0);
        float l = 0.0003 / pow(length(q), 1.5);

        res += l;
    }

    res = res*res;

    return res * COLOR;
}
float rand(vec2 p)
{
    vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
	vec2 M = vec2(0);
    vec4 O=fragColor;

   vec2 ouv = (fragCoord.xy - iResolution.xy * 0.5) / iResolution.x;

    float fCol = 0.;
    float t3 = iTime * 0.25;

    float total = 7.;
    for(float i=1.; i<total; i+=1.){
        float iTotal = i/total;
        float niTotal = 1. - i/total;

        vec2 uv = ouv * (10. + i*1.) - vec2(0., t3*(1.-i/total));
        vec2 id = floor(uv) + vec2(i*1000.);
        uv = fract(uv) - 0.5;

        for(float y=-1.; y<=1.; y+=1.){
            for(float x=-1.; x<=1.; x+=1.){   

                vec2 iuv = uv + vec2(x,y);    
                vec2 iid = id - vec2(x,y);  

                if(rand(iid * 200.) > .25){
                    iuv.x += rand(iid)-.5;
                    iuv.y += rand(vec2(rand(iid)))-.5;        

                    float l = length(iuv * (niTotal)*1.5);  
                    float size = rand(iid*5.)*.1 + .25 - .1;
                    float force = rand(iid*10.)*.5+.5;
                    fCol += 
                        smoothstep(l, l + (iTotal)*.25, size) *                         
                        niTotal *
                        force;        
                }                         
            }
        }        
    }
      vec2 uvs = fragCoord.xy/iResolution.xy;
    vec2 uv3 = (fragCoord*2.-iResolution.xy)/iResolution.y;
      uv3/=1.- uv3.y*1.2*cos(iTime*0.1);
    vec3 col3 = vec3(0.0);

    vec2 p = uv3;


    col3 += CenterLight(p);
 	col3 += Straws(p);
    col3 += Lights(p);

    col3 = max(min(vec3(1.0), col3), vec3(0.0));
    vec3 newFrame = pow(col3, vec3(1./0.8));
    vec3 oldFrame = texture(iChannel0, uvs).rgb;
    vec4 fc2 = vec4(newFrame + oldFrame,1.0)*0.85;

 O-=O;
	for(float i=0.;i<500.;i++)    
    	O+=vec4((1.11-cos((vec3(3,7,1)+i*0.1)))
        	*exp(-9.*length(cross((abs(fract(fract(
                10.*sin((vec3(10,5,9)+i*1.)))+iTime*0.002)*1.0-1.)*1.3-1.)*20.,
                   vec3(gl_FragCoord.xy/iResolution.y-.5,1)))),1)+1e-4;

    float t = iTime*Velocity*0.; 
    vec3 col = vec3(0);  
    for(float i=0.; i<1.; i+=1./NUM_LAYERS){
        float depth = fract(i+t);
        float scale = mix(CanvasView, .5, depth);
        float fade = depth*smoothstep(1.,.9,depth);
        col += StarLayer(uv*scale+i*453.2-iTime*.00)*fade;}   
    fragColor = vec4(col*fCol*5.1*O.xyz*10.+fc2.xyz,1.0);
}
